// Words that were renamed (British → American English): the old id keeps its learning progress.
export const RENAMED_IDS = Object.freeze({
  'ev-holiday': 'ev-vacation',
  'ev-flat': 'ev-apartment',
});

function build(rows, category, prefix) {
  return rows.map(([english, german, exampleEn, exampleDe, cefr, partOfSpeech, acceptedGerman = [], acceptedEnglish = []], index) => ({
    id: `${prefix}-${slugify(english)}`,
    english,
    german,
    exampleEn,
    exampleDe,
    category,
    cefr,
    partOfSpeech,
    acceptedGerman,
    acceptedEnglish,
    frequencyRank: index + 1,
  })).map((v) => (NOTES[v.id] ? { ...v, note: NOTES[v.id] } : v));
}

// The topic words (data/vocabulary-topics.js) come after the original lists: in the normal lesson mix they follow
// the original words of their category; topic lessons take them in the same easy-first order.
const TOPIC_CATEGORY = { dating: 'dating', basics: 'fundamentals' };
function buildTopicWords() {
  return Object.entries(TOPIC_ROWS).flatMap(([topic, rows]) =>
    build(rows, TOPIC_CATEGORY[topic] ?? 'everyday', 'tp').map((v) => ({ ...v, frequencyRank: 1000 + v.frequencyRank })),
  );
}

export const VOCABULARY = [
  ...build(EVERYDAY, 'everyday', 'ev'),
  ...build(DATING, 'dating', 'dt'),
  ...build(FUNDAMENTALS, 'fundamentals', 'fu'),
  ...buildTopicWords(),
];

